#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, cap, flow, cost;
    Edge() {}
    Edge(int y, int cap, int flow, int cost) : y(y), cap(cap), flow(flow), cost(cost) {}
};

vector<Edge> all_edges;
const int MAXNODES = 14043;
vector<int> adj_list[MAXNODES];

long long total_cost_accum = 0;
long long dist_arr[MAXNODES];
int parent_node_arr[MAXNODES], parent_edge_idx[MAXNODES], inq[MAXNODES];

const long long INF_VAL = 1e18;
int s_node = MAXNODES - 2;
int t_node = MAXNODES - 1;

int residual(int idx) {
    return all_edges[idx].cap - all_edges[idx].flow;
}

void find_and_update_flow() {
    for (int i = 0; i < MAXNODES; i++) {
        dist_arr[i] = INF_VAL;
        parent_node_arr[i] = -1;
        parent_edge_idx[i] = -1;
        inq[i] = 0;
    }
    dist_arr[s_node] = 0;
    queue<int> q;
    q.push(s_node);
    inq[s_node] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (auto e_idx : adj_list[u]) {
            if (residual(e_idx) == 0) continue;
            int y = all_edges[e_idx].y;
            int cst = all_edges[e_idx].cost;
            if (dist_arr[y] > dist_arr[u] + cst) {
                dist_arr[y] = dist_arr[u] + cst;
                parent_node_arr[y] = u;
                parent_edge_idx[y] = e_idx;
                if (!inq[y]) {
                    inq[y] = 1;
                    q.push(y);
                }
            }
        }
    }
    int cur = t_node;
    while (cur != s_node) {
        all_edges[parent_edge_idx[cur]].flow++;
        all_edges[parent_edge_idx[cur] ^ 1].flow--;
        cur = parent_node_arr[cur];
    }
    total_cost_accum += dist_arr[t_node];
}

void add_network_edge(int from, int to, int capacity, int cost) {
    adj_list[from].push_back(all_edges.size());
    all_edges.emplace_back(to, capacity, 0, cost);
    adj_list[to].push_back(all_edges.size());
    all_edges.emplace_back(from, 0, 0, -cost);
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x; --x;
        add_network_edge(s_node, x, 1, 0);
    }
    int T = 101;
    for (int i = 0; i < T; i++)
        add_network_edge(i * n, t_node, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y; --x; --y;
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                add_network_edge(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
            }
        }
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                add_network_edge(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < T - 1; j++) {
            add_network_edge(i + j * n, i + j * n + n, k, 0);
        }
    }
    for (int i = 0; i < k; i++) {
        find_and_update_flow();
    }
    cout << total_cost_accum << endl;
}
